export default {
  name: 'AppScanStrategyEdit',
  data() {
    return {
      saving: false,
      enumMap: { class: {}, type: {}, risk: {} },
      vulnList: [],
      vulnTotal: 0,
      vulnPage: 1,
      vulnPageSize: 50,
      selectedVulnIds: [],
      selectedVulnRows: [],
      vulnFilter: { class: null, type: null, risk: null, search: '' },
      portRangeType: 100,
      form: {
        name: '',
        desc: '',
        icon: '',
        config: {
          testMode: 'principle',
          safeTest: true,
          vulExploit: false,
          testIntensity: 3,
          vulIdsConfig: [],
          webCrawler: { isOpen: true, maxDepth: 3, scanRange: 0, crawlerSpeed: 2 },
          portScan: { isOpen: true, scanPort: '21,22,23,80,443,445,3306,8000,8080', tcpScanType: 1, timeout: 10, concurrent: 100 },
          proxy: { isOpen: false, proto: 1, addr: '', port: '' }
        }
      }
    }
  },
  computed: {
    isNew() {
      return !this.$route.query.id || this.$route.query.id === 'new'
    }
  },
  async mounted() {
    this.$store.state.activefirstMenu = '/appsec/tasks'
    await this.fetchEnums()
    this.loadStrategy()
  },
  methods: {
    async fetchEnums() {
      try {
        const res = await tool.vulnerability.getVulObjectlist()
        if (res.code === 200) this.enumMap = res.data
      } catch {
        this.enumMap = {
          class: { 1: 'Web应用', 2: '数据库', 3: '中间件', 4: '操作系统', 5: '安全设备', 6: '应用软件' },
          type: { 1: 'SQL注入', 2: 'XSS', 3: 'SSRF', 4: '命令执行', 5: '文件上传', 6: '文件包含', 7: '信息泄露', 8: '未授权访问', 9: '弱口令', 10: 'CSRF', 11: 'XXE', 12: '逻辑漏洞', 13: '远程代码执行', 14: '组件漏洞' },
          risk: { 0: '严重', 1: '高危', 2: '中危', 3: '低危', 4: '信息' }
        }
      }
      this.fetchVulns()
    },
    loadStrategy() {
      const id = this.$route.query.id
      if (!id || id === 'new') return
      const builtin = this.$route.query.builtin === '1'
      let strategies = []
      if (builtin) {
        try {
          const raw = localStorage.getItem('appsec_builtin_strategies')
          if (raw) strategies = JSON.parse(raw)
        } catch {}
      } else {
        try {
          const raw = localStorage.getItem('appsec_strategies')
          if (raw) strategies = JSON.parse(raw)
        } catch {}
      }
      const s = strategies.find(x => x.id === id)
      if (s) {
        this.form.name = s.name
        this.form.desc = s.desc
        this.form.icon = s.icon
        if (s.config) {
          this.form.config = JSON.parse(JSON.stringify(s.config))
          this.selectedVulnIds = [...(s.config.vulIdsConfig || [])]
        }
      }
    },
    async fetchVulns() {
      try {
        const params = {
          page: this.vulnPage,
          size: this.vulnPageSize,
          libName: this.vulnFilter.search || undefined,
          libClass: this.vulnFilter.class || undefined,
          libType: this.vulnFilter.type || undefined,
          libRisk: this.vulnFilter.risk || undefined
        }
        const res = await tool.vulnerability.getObjectData(params)
        if (res.code === 200) {
          this.vulnList = res.data.list || []
          this.vulnTotal = res.data.total || 0
          this.restoreSelection()
        }
      } catch {
        this.vulnList = []
        this.vulnTotal = 0
      }
    },
    restoreSelection() {
      this.$nextTick(() => {
        if (this.$refs.vulnTable) {
          const rowsToSelect = this.vulnList.filter(v => this.selectedVulnIds.includes(v.id))
          rowsToSelect.forEach(row => {
            this.$refs.vulnTable.toggleRowSelection(row, true)
          })
        }
      })
    },
    onVulnSelectionChange(rows) {
      this.selectedVulnRows = rows
      this.selectedVulnIds = rows.map(r => r.id)
    },
    selectAllVulns() {
      this.vulnList.forEach(row => this.$refs.vulnTable.toggleRowSelection(row, true))
    },
    clearAllVulns() {
      this.$refs.vulnTable.clearSelection()
    },
    onVulnPageChange(page) {
      this.vulnPage = page
      this.fetchVulns()
    },
    onPortRangeChange(val) {
      if (val !== 0) this.form.config.portScan.scanPort = PORT_RANGE_MAP[val] || ''
    },
    riskClass(risk) {
      return ({ 0: 'risk-critical', 1: 'risk-high', 2: 'risk-medium', 3: 'risk-low', 4: 'risk-info' })[risk] || ''
    },
    goBack() {
      this.$router.push('/appsec/strategy')
    },
    async saveStrategy() {
      if (!this.form.name) {
        this.$message({ message: '请输入策略名称', type: 'warning' })
        return
      }
      this.form.config.vulIdsConfig = this.selectedVulnIds
      this.saving = true
      try {
        let strategies = []
        try {
          const raw = localStorage.getItem('appsec_strategies')
          if (raw) strategies = JSON.parse(raw)
        } catch {}

        const id = this.isNew ? 'custom-' + Date.now() : this.$route.query.id
        const existing = strategies.findIndex(x => x.id === id)

        const data = {
          id,
          name: this.form.name,
          desc: this.form.desc,
          icon: this.form.icon || '⚙',
          builtin: false,
          vulnCount: this.selectedVulnIds.length,
          config: JSON.parse(JSON.stringify(this.form.config))
        }

        if (existing >= 0) {
          strategies[existing] = data
        } else {
          strategies.push(data)
        }

        localStorage.setItem('appsec_strategies', JSON.stringify(strategies))
        this.$message({ message: '策略保存成功', type: 'success' })
        this.goBack()
      } catch {
        this.$message({ message: '保存失败', type: 'error' })
      } finally {
        this.saving = false
      }
    }
  }
}
</script>

